def tarantula_fault_suspiciousness(ef: int, nf: int, ep: int, np_count: int) -> float:
    e_f = max(0, int(ef))
    n_f = max(0, int(nf))
    e_p = max(0, int(ep))
    n_p = max(0, int(np_count))
    total_f = e_f + n_f
    total_p = e_p + n_p
    if total_f == 0 or e_f == 0:
        return 0.0
    fail_ratio = e_f / float(total_f)
    if total_p == 0:
        return 1.0
    pass_ratio = e_p / float(total_p)
    if fail_ratio + pass_ratio == 0.0:
        return 0.0
    return fail_ratio / (fail_ratio + pass_ratio)

def git_bisect_midpoint_step(good_idx: int, bad_idx: int) -> int:
    lo = min(int(good_idx), int(bad_idx))
    hi = max(int(good_idx), int(bad_idx))
    if hi - lo <= 1:
        return hi
    return lo + (hi - lo) // 2

def repair_loop_termination_decide(failing_tests: int, attempt: int, max_attempts: int, prev_failing_tests: int) -> int:
    if int(failing_tests) <= 0:
        return 1
    if int(attempt) >= max(1, int(max_attempts)):
        return -1
    if int(attempt) > 1 and int(failing_tests) >= int(prev_failing_tests):
        return -2
    return 0

def weighted_rrf_rank_fusion(lexical_rank: int, semantic_rank: int, k_constant: int, semantic_weight: float) -> float:
    r_lex = max(1, abs(int(lexical_rank)))
    r_sem = max(1, abs(int(semantic_rank)))
    k = max(1, abs(int(k_constant)))
    w = max(0.0, min(1.0, float(semantic_weight)))
    return (1.0 - w) / float(k + r_lex) + w / float(k + r_sem)

def fuzzy_line_anchor_distance(candidate_line: int, expected_line: int, max_drift: int) -> float:
    drift = abs(int(candidate_line) - int(expected_line))
    limit = max(1, abs(int(max_drift)))
    if drift >= limit:
        return 0.0
    return 1.0 - drift / float(limit)

def context_budget_proportional_alloc(total_budget: int, item_weight: float, sum_weights: float, min_floor: int) -> int:
    budget = max(0, int(total_budget))
    floor_val = max(0, min(budget, int(min_floor)))
    w = max(0.0, float(item_weight))
    sw = max(w, float(sum_weights))
    if sw <= 0.0:
        return floor_val
    raw = int(round(budget * (w / sw)))
    return max(floor_val, min(budget, raw))

def circuit_breaker_next_state(current_state: int, consecutive_failures: int, failure_threshold: int, cooldown_elapsed: bool) -> int:
    state = max(0, min(2, int(current_state)))
    fails = max(0, int(consecutive_failures))
    thresh = max(1, int(failure_threshold))
    if state == 2:
        return 1 if cooldown_elapsed else 2
    if state == 1:
        return 2 if fails > 0 else 0
    return 2 if fails >= thresh else 0

def critical_path_duration(stage_max_durations: list[float], overhead_per_stage: float) -> float:
    ov = max(0.0, float(overhead_per_stage))
    pos = [max(0.0, float(d)) for d in stage_max_durations]
    if not pos:
        return 0.0
    return sum(pos) + len(pos) * ov
